import{tools,subjects,exams}from'./data.js';
import{read,write,progress,escape as e,turma}from'./storage.js';
import{study,bank}from'./study.js';
const $=s=>document.querySelector(s),main=$('#main');let filter='Todas',timer=read('missao-focus',{seconds:1500,end:null,completed:0}),frame=null;
const nav=[['home','⌂','Visão geral'],['subjects','▤','Minhas matérias'],['tools','▦','Ferramentas'],['caderno','▱','Meu caderno'],['calendario','▦','Minha agenda'],['games','✚','Aprender jogando'],['assistente','✧','Tutor Neo'],['community','♧','Minha turma']];
$('#navigation').innerHTML=nav.map(([id,icon,title])=>`<a href="#${id}" class="nav-item" data-nav="${id}"><span class="nav-icon">${icon}</span>${title}${id==='games'?'<span class="new-badge">PLAY</span>':''}</a>`).join('');
let dark=read('missao-theme',false);function theme(){document.body.classList.toggle('dark',dark);$('#themeButton span:last-child').textContent=dark?'Modo claro':'Modo escuro';frame?.contentWindow?.postMessage({type:'missao-theme',dark},location.origin)}theme();$('#themeButton').onclick=()=>{dark=!dark;write('missao-theme',dark);theme()};
$('#classSelect').value=turma();$('#classSelect').onchange=()=>{try{localStorage.setItem('portal8-turma-escolhida-v1',$('#classSelect').value)}catch{toast('Não foi possível salvar sua turma.')}route()};
function menu(open){$('#sidebar').classList.toggle('open',open);$('#backdrop').hidden=!open;$('#menuButton').setAttribute('aria-expanded',open);$('#sidebar').inert=matchMedia('(max-width:720px)').matches&&!open}$('#menuButton').onclick=()=>menu(!$('#sidebar').classList.contains('open'));$('#backdrop').onclick=()=>menu(false);document.addEventListener('keydown',ev=>{if(ev.key==='Escape')menu(false);if(ev.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){ev.preventDefault();$('#search').focus()}});
const mobileQuery=matchMedia('(max-width:720px)');mobileQuery.addEventListener('change',()=>menu(false));menu(false);let toastTimeout;function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').style.display='none',4500)}window.addEventListener('storage-failed',()=>toast('Não foi possível salvar. Verifique o espaço disponível no navegador.'));
const title=(heading,description='',extra='')=>`<div class="page-heading"><div><h1>${heading}</h1><p>${description}</p></div>${extra}</div>`;
const quick=(id,name,sub,icon,color)=>`<a class="quick-card" href="#${id}"><span class="tile-icon ${color}">${icon}</span><span class="arrow">↗</span><strong>${name}</strong><small>${sub}</small></a>`;
const subjectCard=s=>`<a class="subject-card" href="#subject/${encodeURIComponent(s[0])}"><span class="tile-icon ${s[2]}">${s[1]}</span><span><strong>${s[0]}</strong><small>${s[3]}</small></span><span class="arrow">›</span></a>`;
function dateNow(){return new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'})}function tasksKey(){return'missao-tasks-'+turma()+'-'+dateNow()}
function agenda(){const next=exams.filter(x=>x[0]>=dateNow()).slice(0,3);return next.length?next.map((x,i)=>`<a href="#calendario" class="agenda-row"><span class="date-square"><b>${x[0].slice(-2)}</b><small>NOV</small></span><div><strong>${x[1]}</strong><p>${x[2]}</p>${i===0?'<span class="tag">PRÓXIMA AVALIAÇÃO</span>':''}</div></a>`).join(''):'<p class="muted" style="padding-top:15px">Consulte o calendário para novas datas.</p>'}
function home(){const p=progress(),tasks=read(tasksKey(),[]);main.innerHTML=title('Seu próximo passo começa aqui.','Um pouco de foco hoje. Muitas possibilidades amanhã.',`<span class="date-pill">▦ ${new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long',timeZone:'America/Sao_Paulo'}).format(new Date())}</span>`)+`<div class="dashboard"><div class="main-column"><section class="hero"><div class="hero-copy"><span class="eyebrow">✦ APRENDA NO SEU RITMO</span><h2>Grandes conquistas.<br>Um estudo de cada vez.</h2><p>Explore conteúdos, pratique o que aprendeu e descubra seu jeito de ir mais longe.</p><a class="button" href="#subjects">Vamos estudar <span>→</span></a></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="art-book"></div><span class="star">✦</span><span class="mini-star">✧</span><div class="art-card"><b>✓</b>Você é capaz.</div></div></section><div class="stats"><div class="stat"><span class="stat-icon">✓</span><div><b>${p.done?.length||0}</b><small>Tópicos concluídos</small></div></div><div class="stat"><span class="stat-icon">◎</span><div><b>${p.answered||0}</b><small>Questões praticadas</small></div></div><div class="stat"><span class="stat-icon">↗</span><div><b>${p.answered?Math.round((p.correct||0)/p.answered*100)+'%':'—'}</b><small>Acertos na prática</small></div></div></div><section><div class="section-title"><h2>Como vamos aprender?</h2><a href="#tools">Todas as ferramentas ↗</a></div><div class="tool-grid">${quick('quiz','Simulados','Pratique e evolua','◎','lavender')}${quick('cartoes','Flashcards','Relembre o essencial','▱','peach')}${quick('mapasNeo','Mapas mentais','Conecte suas ideias','⌘','mint')}${quick('neoEstudio8','Estúdio de estudos','Crie seus materiais','✧','blue')}</div></section><section class="subjects-section"><div class="section-title"><h2>Suas matérias</h2><a href="#subjects">Ver todas as 8 →</a></div><div class="subject-grid">${subjects.slice(0,4).map(subjectCard).join('')}</div></section><div class="community"><span>♧</span><div><strong>Aprender é melhor juntos.</strong><p>Materiais, missões e descobertas da turma ${turma()}.</p></div><a href="#community">Explorar →</a></div></div><aside class="right-column"><section class="panel focus-panel"><div class="section-title"><h2>Hora de focar</h2><span>◷</span></div><p>Um momento só para aprender.</p><div class="clock" id="clock">25:00</div><span class="timer-label" id="timerLabel">SESSÃO DE CONCENTRAÇÃO</span><div class="timer-actions"><button class="button" id="timerToggle">▷ Começar foco</button><button class="reset-timer" id="timerReset" aria-label="Reiniciar cronômetro">↻</button></div></section><section class="panel"><div class="section-title"><h2>No seu radar</h2><a href="#calendario">Ver agenda ↗</a></div>${agenda()}<p class="agenda-note">Datas do portal original. Confirme com seus professores.</p></section><section class="panel daily"><div class="section-title"><h2>Pequenas metas de hoje</h2><span class="daily-count" id="taskCount">${tasks.length}/3</span></div>${['Revisar um conteúdo','Praticar 5 questões','Fazer uma pausa'].map((t,i)=>`<label class="task"><input type="checkbox" data-task="${i}" ${tasks.includes(i)?'checked':''}><span>${t}</span></label>`).join('')}<div class="progress-track"><i id="taskProgress" style="width:${tasks.length/3*100}%"></i></div></section></aside></div>`;
$('#timerToggle').onclick=toggleTimer;$('#timerReset').onclick=()=>{timer.seconds=1500;timer.end=null;saveTimer();tick()};main.querySelectorAll('[data-task]').forEach(input=>input.onchange=()=>{const done=[...main.querySelectorAll('[data-task]:checked')].map(i=>+i.dataset.task);write(tasksKey(),done);$('#taskCount').textContent=done.length+'/3';$('#taskProgress').style.width=done.length/3*100+'%'});tick()}
function saveTimer(){write('missao-focus',timer)}function toggleTimer(){if(timer.end){timer.seconds=Math.max(0,Math.ceil((timer.end-Date.now())/1000));timer.end=null}else{if(!timer.seconds)timer.seconds=1500;timer.end=Date.now()+timer.seconds*1000}saveTimer();tick()}
function tick(){let remaining=timer.end?Math.max(0,Math.ceil((timer.end-Date.now())/1000)):timer.seconds;if(timer.end&&remaining===0){timer.end=null;timer.seconds=0;timer.completed++;saveTimer();toast('Sessão concluída! Faça uma pausa de 5 minutos.')}if($('#clock')){$('#clock').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');$('#timerToggle').textContent=timer.end?'Ⅱ Pausar foco':'▷ Começar foco';$('#timerLabel').textContent=remaining===0?'HORA DE FAZER UMA PAUSA':'SESSÃO DE CONCENTRAÇÃO'}}setInterval(tick,1000);
function directory(category='',query=''){const categories=['Todas',...new Set(tools.map(t=>t[3]))];const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const list=tools.filter(t=>(!category||category==='Todas'||t[3]===category)&&(!query||norm(t.slice(1,4).join(' ')).includes(norm(query))));main.innerHTML=title(query?'Encontre seu próximo passo.':category==='Explorar'?'Aprender também é explorar.':category==='Comunidade'?'Sua turma, mais perto.':'Tudo o que você precisa para estudar.',query?`Resultados para “${e(query)}”`:'Escolha uma ferramenta e comece do seu jeito.')+(!category||category==='Todas'?`<div class="filters">${categories.map(c=>`<button class="chip ${filter===c?'active':''}" data-filter="${c}">${c}</button>`).join('')}</div>`:'')+`<div class="directory">${list.map((t,i)=>quick(t[0],t[1],t[2],t[4],['mint','lavender','peach','blue'][i%4])).join('')}</div>${!list.length?'<div class="empty">Nenhuma ferramenta encontrada. Tente “caderno”, “jogos” ou “mapas”.</div>':''}`;main.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;directory();if(filter!=='Todas'){const ids=new Set(tools.filter(t=>t[3]===filter).map(t=>t[0]));main.querySelectorAll('.quick-card').forEach(a=>a.hidden=!ids.has(a.hash.slice(1)))}})}
async function subjectPage(name){const s=subjects.find(s=>s[0]===name);if(!s){location.hash='subjects';return}main.innerHTML=title(e(name),s[3])+`<div class="button-row" style="justify-content:start;margin-bottom:25px"><a class="button" href="#quiz/${encodeURIComponent(name)}">Praticar questões →</a><a class="button secondary" href="#cartoes/${encodeURIComponent(name)}">Revisar flashcards</a><a class="button secondary" href="#trilha">Abrir trilha completa</a></div><div id="topics" class="topic-list"></div>`;const host=$('#topics');try{const all=await bank();if(!host.isConnected)return;const topics=[...new Set(all.filter(q=>q.subject===name).map(q=>q.topic))];host.innerHTML=topics.map(t=>`<a href="#quiz/${encodeURIComponent(name)}/${encodeURIComponent(t)}"><span>${e(t)}</span><span class="muted">→</span></a>`).join('')}catch{host.textContent='Não foi possível carregar os assuntos. Tente novamente.'}}
function modulePage(id){const t=tools.find(t=>t[0]===id);if(!t){location.hash='home';return}main.innerHTML=title(e(t[1]),e(t[2]),'<a class="button secondary" href="#tools">← Ferramentas</a>')+`<div class="module-wrap"><p class="module-loading" id="moduleLoading" role="status">Carregando ferramenta…</p><iframe class="module-frame" id="moduleFrame" title="${e(t[1])}" src="modules/index.html?embedded=1&tool=${encodeURIComponent(({quizOriginal:'quiz',cartoesOriginal:'cartoes'})[id]||id)}&theme=${dark?'dark':'light'}" allow="fullscreen"></iframe></div>`;frame=$('#moduleFrame');frame.onload=()=>{if($('#moduleLoading'))$('#moduleLoading').remove();theme()};}
function about(){main.innerHTML=title('Uma base melhor para aprender.','Análise, arquitetura e limites desta primeira versão.')+`<article class="panel prose"><h2>1. O que mudou</h2><table><thead><tr><th>No original</th><th>Nesta versão</th></tr></thead><tbody><tr><td>Vários banners e caminhos repetidos</td><td>Painel único, busca e catálogo por categoria</td></tr><tr><td>43 scripts externos e 21 folhas de estilo no HTML</td><td>Entrada leve; módulos originais carregados sob demanda</td></tr><tr><td>Estilos acumulados em várias versões</td><td>Tokens visuais, Grid, Flexbox e regras responsivas</td></tr><tr><td>Navegação extensa em telas pequenas</td><td>Menu recolhível, busca e áreas de toque acessíveis</td></tr></tbody></table><h2>2. Design</h2><p>Uma identidade própria de estudo: verde sálvia, azul-escuro, superfícies claras e tipografia legível. Modo escuro, foco visível no teclado e respeito à preferência por movimento reduzido.</p><h2>3. Arquitetura e código</h2><p>HTML semântico, CSS responsivo e módulos JavaScript nativos: navegação, dados, armazenamento e sessões de estudo separados. O código não exige compilação. A pasta <code>modules/</code> preserva os motores originais em um documento isolado, aberto sob demanda. É uma migração incremental: os módulos avançados ainda utilizam o código anterior.</p><p>O banco complementar contém 243 questões de oito matérias. Os simulados novos embaralham alternativas, evitam repetição até esgotar o conjunto e explicam cada resposta. Os módulos originais continuam disponíveis, incluindo seus bancos e recursos adicionais. Isso não é uma certificação de cobertura integral do currículo.</p><h2>Dados e integrações</h2><p>Progresso e metas ficam neste navegador. Este endereço tem armazenamento separado do GitHub Pages: use a exportação/importação da trilha e do caderno para transferir seus dados. Os módulos de comunidade e conta mantêm a conexão Supabase original; fluxos de e-mail e Google exigem URLs de retorno autorizadas para este endereço. O tutor continua sendo um motor local, não uma IA generativa.</p><p>O projeto Supabase original foi identificado e está ativo. As 17 tabelas públicas consultadas usam RLS. Nenhuma tabela, conta, política ou configuração de autenticação foi alterada nesta entrega. Login autenticado e escritas coletivas exigem validação com uma sessão real do usuário.</p><h2>Fontes e continuidade</h2><p>Base preservada de <a href="https://github.com/miguelhenriquecostaaraujo13-cmd/Missao-803" target="_blank" rel="noopener">Missao-803 no GitHub ↗</a>. As datas de provas foram transcritas do portal original e devem ser confirmadas com a escola. Projeto colaborativo independente, não oficial da instituição.</p><a href="https://github.com/miguelhenriquecostaaraujo13-cmd/Missao-803/tree/redesign/experiencia-estudos/redesign" class="button download" target="_blank" rel="noopener">Ver código completo no GitHub ↗</a></article>`}
function route(){frame=null;menu(false);const parts=location.hash.slice(1).split('/');let id=parts[0]||'home';if(id==='main'){main.focus();return}$('#crumb').textContent=nav.find(n=>n[0]===id)?.[2]||tools.find(t=>t[0]===id)?.[1]||'Estudos';document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===id||(id==='subject'&&a.dataset.nav==='subjects');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});let args;try{args=parts.slice(1).map(decodeURIComponent)}catch{args=[]}switch(id){case'home':home();break;case'subjects':main.innerHTML=title('Um mundo de descobertas.','Oito matérias. Escolha por onde você quer começar.')+`<div class="subject-grid large-grid">${subjects.map(subjectCard).join('')}</div>`;break;case'subject':subjectPage(args[0]);break;case'tools':filter='Todas';directory();break;case'games':directory('Explorar');break;case'community':directory('Comunidade');break;case'quiz':case'cartoes':main.innerHTML=title(id==='quiz'?'Pratique. Entenda. Evolua.':'Uma ideia de cada vez.',id==='quiz'?'Questões comentadas para transformar dúvidas em aprendizado.':'Tente lembrar antes de revelar a resposta.')+'<section id="studyRoot"></section>';study($('#studyRoot'),id==='quiz'?'quiz':'flash',args[0],args[1]);break;case'about':about();break;default:modulePage(id)}window.scrollTo(0,0)}
let searchTimeout;$('#search').addEventListener('input',()=>{clearTimeout(searchTimeout);searchTimeout=setTimeout(()=>{const q=$('#search').value.trim();if(q){directory('',q);$('#crumb').textContent='Busca'}else route()},120)});
window.addEventListener('hashchange',()=>{$('#search').value='';route()});window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==frame?.contentWindow)return;if(event.data?.type==='missao-route'&&event.data.id==='inicio')location.hash='home'});route();
